Custom span around business logic:
import { trace } from '@opentelemetry/api';
const tracer = trace.getTracer('shop');
async function placeOrder(input) {
return tracer.startActiveSpan('placeOrder', async (span) => {
span.setAttribute('user.id', input.user_id);
span.setAttribute('items.count', input.items.length);
try {
const result = await db.collection('orders').insertOne({ ... });
span.setAttribute('order.id', result.insertedId.toString());
return result;
} catch (err) {
span.recordException(err);
span.setStatus({ code: 2 /* ERROR */ });
throw err;
} finally {
span.end();
}
});
}
